package com.honorablemobile

import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34], manifest = Config.NONE, application = android.app.Application::class)
class VideoFinishGuideTest {
 private fun clips()=listOf(VideoSegment(0,5000,speed=2f,title="First"),VideoSegment(5000,8000,title="Second"))
 private fun info(mode:EditorAccessMode=EditorAccessMode.GUEST_BASIC)=VideoFinishGuide.describe(clips(),0,1000,3000,mode)
 @Test fun summaryUsesActualExportSelectionAndOtherStoredRanges(){val i=info();assertTrue(i.summary.contains("2 clips"));assertTrue(i.summary.contains("00:00:04,000"));assertEquals(8_000_000L,VideoPlaybackTime.durationUs(listOf(VideoSegment(0,8000))))}
 @Test fun guestAndAccountOfferExistingRoutesWithAppropriateQuickSave(){for(mode in EditorAccessMode.values()){val actions=info(mode).choices.map{it.action};assertTrue(actions.contains(VideoFinishGuide.Action.VIDEO_COPY));assertTrue(actions.contains(VideoFinishGuide.Action.NAMED_VERSION));assertEquals(mode==EditorAccessMode.GUEST_BASIC||mode.allowsAccountDrafts,actions.contains(VideoFinishGuide.Action.QUICK_SAVE));assertEquals(actions.size,actions.distinct().size)}}
 @Test fun choicesExplainPlayableAndEditableOutcomes(){val choices=info().choices;assertTrue(choices.single{it.action==VideoFinishGuide.Action.VIDEO_COPY}.detail.contains("MP4"));assertTrue(choices.single{it.action==VideoFinishGuide.Action.NAMED_VERSION}.detail.contains("editable"));assertTrue(choices.single{it.action==VideoFinishGuide.Action.QUICK_SAVE}.title.contains("project"));assertTrue(info(EditorAccessMode.ACCOUNT).choices.single{it.action==VideoFinishGuide.Action.QUICK_SAVE}.title.contains("draft"))}
 @Test fun invalidExportRangeOrSelectionDoesNotPrepareGuide(){for(args in listOf(Triple(0,-1L,2000L),Triple(0,1000L,6000L),Triple(0,2000L,1000L),Triple(5,0L,1000L))){try{VideoFinishGuide.describe(clips(),args.first,args.second,args.third,EditorAccessMode.GUEST_BASIC);fail("Invalid guide range")}catch(_:IllegalArgumentException){}}}
 @Test fun choiceListsAndAllowedActionsAreDefensive(){val choices=info().choices.toMutableList();val prepared=VideoFinishGuide.Info("Summary",choices);val actions=choices.map{it.action}.toMutableList();val route=VideoFinishGuide.Route(actions){true};choices.clear();actions.clear();assertEquals(3,prepared.choices.size);var result:VideoFinishGuide.Action?=null;assertTrue(route.choose(VideoFinishGuide.Action.VIDEO_COPY,{}){result=it});assertEquals(VideoFinishGuide.Action.VIDEO_COPY,result)}
 @Test fun explicitChoiceDismissesBeforeOneDispatch(){val order=mutableListOf<String>();val r=VideoFinishGuide.Route(listOf(VideoFinishGuide.Action.VIDEO_COPY)){true};assertTrue(r.choose(VideoFinishGuide.Action.VIDEO_COPY,{order.add("dismiss")}){order.add(it.name)});assertEquals(listOf("dismiss","VIDEO_COPY"),order);assertFalse(r.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss twice")}){fail("dispatch twice")})}
 @Test fun cancelledGuideCannotDispatch(){val r=VideoFinishGuide.Route(VideoFinishGuide.Action.values().toList()){true};r.close();r.close();assertFalse(r.choose(VideoFinishGuide.Action.QUICK_SAVE,{fail("dismiss")}){fail("save")})}
 @Test fun changedContextClosesRoutePermanently(){var valid=false;val r=VideoFinishGuide.Route(VideoFinishGuide.Action.values().toList()){valid};assertFalse(r.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss")}){fail("export")});valid=true;assertFalse(r.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss")}){fail("revived")})}
 @Test fun unofferedChoiceCannotReachDispatch(){val r=VideoFinishGuide.Route(listOf(VideoFinishGuide.Action.NAMED_VERSION)){true};assertFalse(r.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss")}){fail("export")});assertTrue(r.choose(VideoFinishGuide.Action.NAMED_VERSION,{}){})}
 @Test fun throwingDispatchCannotBeReplayed(){val r=VideoFinishGuide.Route(listOf(VideoFinishGuide.Action.VIDEO_COPY)){true};try{r.choose(VideoFinishGuide.Action.VIDEO_COPY,{}){error("Tool failed")};fail("Expected exception")}catch(_:IllegalStateException){};assertFalse(r.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss")}){fail("retry")})}
 @Test fun preparingAndClosingGuideLeavesProjectMusicAndHistoryUntouched(){val p=VideoEditProject(8000);val music=VideoSoundtrack("content://synthetic/music",10000,loop=false);p.restore(clips(),soundtrack=music);val old=p.segments;val i=VideoFinishGuide.describe(p.segments,0,1000,3000,EditorAccessMode.GUEST_BASIC);val route=VideoFinishGuide.Route(i.choices.map{it.action}){true};route.close();assertSame(old,p.segments);assertSame(music,p.soundtrack);assertFalse(p.canUndo);assertFalse(p.canRedo)}
 @Test fun openingRouteDoesNotEvaluateOrDispatchAnyAction(){var checks=0;val r=VideoFinishGuide.Route(info().choices.map{it.action}){checks++;true};assertEquals(0,checks);r.close();assertEquals(0,checks)}
 private val unsafe=JvmTestAllocator
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(8000);p.restore(clips());set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"durationMs",8000);set(it,"primaryDurationMs",8000L);set(it,"workspaceActive",true);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun context(a:HonorableVideoEditorActivity):Pair<android.app.AlertDialog,VideoCaptionReviewState>{val state=call(a,"captureCaptionReview")as VideoCaptionReviewState;val d=unsafe.allocateInstance(android.app.AlertDialog::class.java)as android.app.AlertDialog;android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,unsafe.allocateInstance(android.view.View::class.java));set(a,"captionReviewDialogs",linkedSetOf(d));return d to state}
 @Test fun actualPausedBusyRecoveryGuideEntryReturnsBeforeWidgets(){for(flag in listOf("workspaceActive","saving","importing","draftBusy","recoveryBlocked","recoveryChecking")){val a=activity();set(a,flag,flag!="workspaceActive");call(a,"videoFinishGuide");assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun actualChangedSourcePreventsGuideDispatch(){val a=activity();val(d,s)=context(a);val route=VideoFinishGuide.Route(info().choices.map{it.action}){call(a,"activeCaptionReviewDialog",d,s)as Boolean};set(a,"source",Uri.parse("content://synthetic/other"));assertFalse(route.choose(VideoFinishGuide.Action.QUICK_SAVE,{fail("dismiss")}){fail("save")})}
 @Test fun actualDismissedDialogPreventsGuideDispatch(){val a=activity();val(d,s)=context(a);val route=VideoFinishGuide.Route(info().choices.map{it.action}){call(a,"activeCaptionReviewDialog",d,s)as Boolean};android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,null);assertFalse(route.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss")}){fail("export")})}
 @Test fun actualCurrentContextRoutesOnlyOneExplicitExistingAction(){val a=activity();val(d,s)=context(a);val p=get(a,"project")as VideoEditProject;val before=p.segments;val actions=mutableListOf<VideoFinishGuide.Action>();val route=VideoFinishGuide.Route(info().choices.map{it.action}){call(a,"activeCaptionReviewDialog",d,s)as Boolean};assertTrue(route.choose(VideoFinishGuide.Action.NAMED_VERSION,{set(a,"captionReviewDialogs",linkedSetOf<android.app.AlertDialog>())}){actions.add(it)});assertEquals(listOf(VideoFinishGuide.Action.NAMED_VERSION),actions);assertFalse(route.choose(VideoFinishGuide.Action.VIDEO_COPY,{fail("dismiss")}){fail("export")});assertSame(before,p.segments);assertFalse(p.canUndo)}
}
